  // frame
  dotSize = [0, 6];
  NYLine(padding, padding, padding, height - padding);
  NYLine(width - padding, padding, width - padding, height - padding);
  NYLine(padding, height - padding, width - padding, height - padding);


	dotSize = [1, 3];

  // draw last cloud white
  var nowPath = cloudPaths[cloudPaths.length - 1];

  // fill cloud path
  for (let i = 0; i < nowPath.length; i++) {
    var x1 = nowPath[i].x;
    var y1 = nowPath[i].y;

    var x2 = x1;
    var y2 = height;

    stroke(240);
    line(x1, y1, x2, y2);

    if (i % 100 == 0)
      await sleep(sleepTimer);
  }

  // draw cloud path
  var shadeNX = random(-1000, 1000);
